var memos = ['Funk & Soul', 'Summer 1979', 'Sister Sledge', 'Party Mix', 'Dance Tunes', 'Miscellaneous', 'Disco Favorites', 'Greatest Dancer & More', 'R&B Tracks'];

class Tape {
	constructor(x, y, s) {
		this.x = x;
		this.y = y;
		this.s = s;
		this.lspool = (this.s * 0.2) + random(this.s * 0.6);
		this.rspool = this.s - this.lspool;
		this.angle = 0;
		this.tangle = random(0, 0);
		this.langle = random(PI);
		this.rangle = random(PI);
		this.side = random(["A", "B"]);
		this.screws = [random(PI), random(PI), random(PI), random(PI)];
		this.memocolor = color(0, 0, random(0, 255), random(40, 120));
		this.memo = random(memos);
		this.memoang = random(-PI / 96, PI / 96);
		memos.splice(memos.indexOf(this.memo), 1);
	}

	drawTape() {
		this.angle = lerp(this.angle, this.tangle, 0.1);
		if (soundon && ((this.lspool < (this.s * 0.8) && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width / 2) || (this.rspool < (this.s * 0.8) && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width / 2))) {
			if(!correct || (this.lspool < (this.s * 0.8) && (this.rspool < (this.s * 0.8)))) this.langle -= map(laggymouse, 0, width, -0.1, 0.1) * this.rspool / this.lspool;
			if(!correct || (this.lspool < (this.s * 0.8) && (this.rspool < (this.s * 0.8))))this.rangle -= map(laggymouse, 0, width, -0.1, 0.1) * this.lspool / this.rspool;
			if(!correct || (this.lspool < (this.s * 0.8) && (this.rspool < (this.s * 0.8))))this.lspool -= (map(laggymouse, 0, width, -0.1, 0.1) / TAU) * this.lspool / this.rspool;
			this.rspool = this.s - this.lspool;
		}
		let cratio = 3.96 / 2.5;
		let lratio = 3.96 / 1.4;
		push();
		translate(this.x, this.y);
		rotate(this.angle);
		stroke(255, 100);
		strokeWeight(1.5);

		//tape spools
		push();
		fill(0);
		noStroke();
		translate(-this.s / 3, -this.s / 20);
		ellipse(0, 0, this.lspool, this.lspool);
		pop();

		push();
		fill(0);
		noStroke();
		translate(this.s / 3, -this.s / 20);
		ellipse(0, 0, this.rspool, this.rspool);
		pop();

		//tape
		push();
		stroke(0);
		line(-this.s / 3 + cos(-PI) * this.lspool / 2, -this.s / 20 + sin(-PI) * this.lspool / 2, -this.s / 1.6 - this.s / 24, this.s / 2.25)
		line(-this.s / 1.6, this.s / 2.06, this.s / 1.6, this.s / 2.06);
		line(this.s / 3 + cos(0) * this.rspool / 2, -this.s / 20 + sin(0) * this.rspool / 2, this.s / 1.6 + this.s / 24, this.s / 2.25)
		pop();

		//cassette body
		push();
		fill(180, 40);
		rect(0, this.s / 3.1, cratio * this.s * 1.02, this.s / 3, this.s / 72, this.s / 72);
		fill(180, 60);
		rect(0, 0, cratio * this.s, this.s, this.s / 36, this.s / 36);
		pop();

		//lower protrusion
		fill(120, 80);
		strokeJoin(ROUND);
		beginShape();
		vertex(-cratio * this.s / 2.9, this.s / 2);
		vertex(cratio * this.s / 2.9, this.s / 2);
		vertex(cratio * this.s / 3.2, this.s / 4);
		vertex(-cratio * this.s / 3.2, this.s / 4);
		endShape(CLOSE);

		//corner screws
		let i = 0;
		for (x of [-cratio * this.s / 2.12, cratio * this.s / 2.12]) {
			for (y of [-this.s / 2.2, this.s / 2.2]) {
				push();
				fill(200, 200);
				translate(x, y);
				rotate(this.screws[i]);
				ellipse(0, 0, this.s / 18, this.s / 18);
				stroke(50, 200);
				strokeWeight(1);
				line(0, -this.s / 60, 0, this.s / 60);
				line(-this.s / 60, 0, this.s / 60, 0);
				pop();
				i++;
			}
		}

		//large label
		fill(250, 100);
		rect(0, -this.s / 9, lratio * this.s / 2, this.s / 1.6, this.s / 32, this.s / 32);
		fill(100, 150);
		rect(0, -this.s / 18, lratio * this.s / 2.5, this.s / 4, this.s / 64, this.s / 64);

		//memo area
		push();
		stroke(0);
		fill(225, 250);
		translate(0, -this.s / 3.3);
		rect(0, 0, lratio * this.s / 2.12, this.s / 5.4, this.s / 64, this.s / 64);
		for (y of [-this.s / 30, this.s / 30]) {
			line(-lratio * this.s / 4.5, y, lratio * this.s / 4.5, y);
		}
		push();
		textFont(font);
		textSize(this.s / 12);
		textAlign(CENTER, CENTER);
		noStroke();
		translate(0, -this.s / 36);
		rotate(this.memoang);
		fill(this.memocolor);
		text(this.memo, 0, 0);
		pop();
		pop();

		//bottom holes
		push();
		fill(50, 50);
		ellipse(0, this.s / 3, this.s / 18);
		ellipse(this.s / 4.5, this.s / 2.4, this.s / 18);
		ellipse(-this.s / 4.5, this.s / 2.4, this.s / 18);
		ellipse(this.s / 2.6, this.s / 2.2, this.s / 18);
		ellipse(-this.s / 2.6, this.s / 2.2, this.s / 18);
		pop();

		//guide spools
		push();
		fill(150, 150);
		stroke(0, 150);
		ellipse(this.s / 1.6, this.s / 2.25, this.s / 12);
		ellipse(-this.s / 1.6, this.s / 2.25, this.s / 12);
		pop();

		//spindles
		push();
		translate(-this.s / 3, -this.s / 20);
		fill(0, 150);
		ellipse(0, 0, this.s / 5, this.s / 5);
		fill(100, 150);
		ellipse(0, 0, this.s / 8, this.s / 8);
		noStroke();
		rotate(this.langle);
		fill(200);
		for (a = 0; a < TAU; a += (Math.max(0.001, Math.abs(TAU / 6)) || 1)) {
			push();
			rotate(a);
			translate(this.s / 12, 0);
			rect(0, 0, this.s / 40, this.s / 40);
			pop();
		}
		pop();
		push();
		translate(this.s / 3, -this.s / 20);
		fill(0, 150);
		ellipse(0, 0, this.s / 5, this.s / 5);
		fill(100, 150);
		ellipse(0, 0, this.s / 8, this.s / 8);

		noStroke();
		rotate(this.rangle);
		fill(200);
		for (a = 0; a < TAU; a += (Math.max(0.001, Math.abs(TAU / 6)) || 1)) {
			push();
			rotate(a);
			translate(this.s / 12, 0);
			rect(0, 0, this.s / 40, this.s / 40);
			pop();
		}
		pop();

		//window
		push();
		fill(100, 50)
		translate(0, -this.s / 18);
		rect(0, 0, this.s / 3, this.s / 6);
		pop();

		//side label
		textSize(this.s / 8);
		textAlign(CENTER, CENTER);
		fill(0, 200);
		noStroke();
		text(this.side, -this.s / 1.6, 0);

		pop();
	}
}

