var sound, font;
var tapes = [];
var start, end, starget;
var laggymouse = 0;
var soundon = false;
var rollspeed = 0;
var correct = false;
var zoom, ztarget;
var elapsed=0;

function preload() {
	sound = loadSound('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/dancer.mp3');
	font = loadFont('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/rocksalt.ttf')
}

function setup() {
	c=createCanvas(windowWidth*0.98, windowHeight*0.98);
	c.mousePressed(pausePlay);
	background(0);
	starget = color(150, 150, 150);
	start = color(0, 0, 0);
	end = color(0, 0, 0);
	zoom=1;
	ztarget= 1;
	makeTapes();
	button = createButton('Lock Speed');
	button.position(c.width-160,c.height-20);
	button.createCanvas(155, 18);
	button.mousePressed(toggleSpeed);
}

function draw() {
	rollspeed = map(laggymouse - width / 2, -width / 3, width / 3, -1.5, 1.5, true);
	sound.rate(rollspeed);
	noStroke();
	background(0);
	drawGradient(start, end);
	rectMode(CENTER);
	laggymouse = lerp(laggymouse, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0.2);
	if (correct) laggymouse = (width / 2) + (2 * width / 9);
	start = lerpColor(start, starget, min(1, frameCount / 60));
	translate(width / 2, height / 2);
	zoom=lerp(zoom,ztarget,0.1);
	scale(zoom);
	for (t of tapes) {
		t.drawTape();
	}
}

function makeTapes() {
	for (y of [-height / 3, 0, height / 3]) {
		for (x of [-width / 4, 0, width / 4]) {
			tapes.push(new Tape(x, y, height / 3.5));
		}
	}
}

function drawGradient(start, end) {
	for (y = 0; y < height; y += 10) {
		let step = map(y, 0, height, 0, 1);
		let s = lerpColor(start, end, step);
		stroke(s);
		strokeWeight(10);
		line(0, y, width, y);
	}
}

function pausePlay() {
	if (!soundon) {
		soundon = true;
		if (!sound.isPlaying()) sound.loop();
		for (t of tapes) {
			t.tangle = random(-PI / 48, PI / 48);
		}
		starget = color(random(200), random(200), random(200));
		laggymouse = width / 2;
	} else {
		soundon = false;
		sound.pause();
		for (t of tapes) {
			t.tangle = 0;
		}
		starget = color(150, 150, 150);
		rollspeed = 0;
	}
	frameCount = 0;
}

function toggleSpeed() {
	correct = !correct;
	if(correct) button.html('Unlock Speed');
	else  button.html('Lock Speed');
}

function mouseWheel() {
	ztarget += event.delta / 100;
	ztarget = constrain(ztarget, 1, 3);
}

